mapper.select:
select doi.id, doi.platform_order_id, doi.source_platform, doi.shop_name, case when doi.currency_rate != 0 then round(doi.order_fee/doi.currency_rate,4) else 0 end as itemTotal, doi.order_fee as cnyRealTimeAmount, case when doi.currency_rate != 0 then round(doi.order_fee/doi.currency_rate * doi.cny_settle_rate,4) else 0 end as cny_settle_amount, doi.buyer_name, doi.man_phone, doi.second_phone, doi.man_street, doi.second_street, doi.country_name_cn, doi.order_state, doi.correction_status, doi.create_time, doi.platform_order_id, doi.delivery_time, doi.charge_name, doi.dept_name, doi.platform_create_time from dmp_order_info doi
and doi.platform_order_id = #{params.platformOrderId}
and doi.shop_name = #{params.shopName}
and doi.source_platform = #{params.platformName}
and doi.order_state = #{params.orderState}
and doi.platform_create_time >= #{params.createTime_begin}::timestamp
and doi.platform_create_time <= #{params.createTime_end}::timestamp
and doi.delivery_time >= #{params.deliveryTime_begin}::timestamp
and doi.delivery_time <= #{params.deliveryTime_end}::timestamp
${params.permissionSql}

SELECT ${groupName} AS dimension,
SUM(doit.afer_amount) AS salesAmount
FROM dmp_order_info AS doi
left join  dmp_order_item AS doit on doi.id = doit.order_id
WHERE doi.${groupName} IS NOT NULL

    AND doi.platform_create_time >= #{params.startTime}


    AND doi.platform_create_time <= #{params.endTime}

/*部门*/

    AND doi.dept_id IN

        #{deptId}


/*平台*/

    AND doi.platform_name IN

        #{platform}


/*站点*/

    AND doi.site IN

        #{site}



/*店铺*/

    AND doi.shop_no IN

        #{shopNo}


/*用户id*/

    AND doi.charge_id IN

        #{userId}




    #{params.permissionSql}

GROUP BY doi.${groupName}

